import { TestBed } from '@angular/core/testing';
import { HttpClient, provideHttpClient, withInterceptors } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { fixtureBackendInterceptor } from './core/fixture-backend/fixture-backend.interceptor';
import { FixtureBackendState } from './core/fixture-backend/fixture-backend.state';

describe('debug', () => {
  it('builds dataset', async () => {
    TestBed.configureTestingModule({ providers: [provideHttpClient(withInterceptors([fixtureBackendInterceptor]))] });
    const state = TestBed.inject(FixtureBackendState);
    const ds = state.dataset;
    console.log(Object.keys(ds), ds.session);
    const s = await firstValueFrom(TestBed.inject(HttpClient).get('http://localhost:4501/v1/session'));
    console.log(s);
  });
});
